const cmds = [
  ["tests", "rtk bun test"],
  ["build", "rtk bun run build"],
  ["tools-check", "rtk bun run tools:check"],
  ["tools-test", "rtk bun run tools:test"],
  ["lint", "rtk bun run lint"]
];
const results = await Promise.all(cmds.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:"/home/diogenes/Projects/twyne", yield_time_ms:1000, max_output_tokens:5000});
  return {name, ...r};
}));
for (const r of results) {
  text(`=== ${r.name} ===\n${r.output}`);
  if (r.session_id) text(`SESSION ${r.name} ${r.session_id}`);
}

const ids = [91939,55643,76178,79122];
for (const id of ids) {
  const r = await tools.write_stdin({session_id:id, chars:"", yield_time_ms:1000, max_output_tokens:4000});
  text(`=== ${id} ===\n${r.output}${r.session_id ? `\nSESSION ${r.session_id}` : `\nEXIT ${r.exit_code}`}`);
}

const patch = "*** Begin Patch
*** Add File: /home/diogenes/Projects/twyne/.bumpy/steady-release-marker.md
+---
+---
*** End Patch";
text(await tools.apply_patch(patch));

